import {RailGame} from './engine.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const game=new RailGame();let scene,tab='queue',sound=false,audio,toastTimer,modalResume=false,modalType='',lastUI=0,lastTime=performance.now(),resultShown=false;
const statusNames={scheduled:'计划中',queued:'等待进站',incoming:'进站运行',working:'站内作业',ready:'等待出站',outgoing:'出站运行',done:'已交付'};
const icons={train:'<svg><use href="#i-train"/></svg>',box:'<svg><use href="#i-box"/></svg>'};
function clock(t,seconds=true){const base=game.mode==='night'?22:6;const m=Math.floor(t/60),s=Math.floor(t%60);return `${String(base).padStart(2,'0')}:${String(m).padStart(2,'0')}${seconds?':'+String(s).padStart(2,'0'):''}`}
function beep(kind='ok'){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(kind==='warn'?230:620,audio.currentTime);o.frequency.exponentialRampToValueAtTime(kind==='warn'?170:880,audio.currentTime+.12);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.25);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.26)}catch{}}
function toast(message,ok=true){const e=$('#toast');e.textContent=message;e.className='toast show'+(ok?'':' warn');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),3400);beep(ok?'ok':'warn')}
function respond(r){toast(r.message,r.ok);render();return r}
function dispatch(id=game.selected){if(!game.started){game.start();toast('值班开始。先开放信号，让列车进入空闲股道。');render();return {ok:true,message:'值班已开始，请再次开放信号'}}return respond(game.dispatch(id))}
function select(id){game.select(id);render()}
function render(){
 $('#money').textContent='¥ '+game.money.toLocaleString();$('#punctuality').innerHTML=game.punctuality+'<span>%</span>';$('#safety').innerHTML=game.safety+'<span>/100</span>';$('#delivered').textContent=game.delivered;
 $('#clock').textContent=clock(game.time);$('#runningLabel').textContent=game.ended?'值班已结束':game.running?'值班进行中':game.started?'调度已暂停':'等待交班';$('#playButton').innerHTML=game.ended?'↻ <span>再开一班</span>':game.running?'Ⅱ <span>暂停调度</span>':game.started?'▶ <span>继续值班</span>':'▶ <span>开始值班</span>';
 $('#shiftProgress').style.width=game.time/game.duration*100+'%';$('#weather').textContent=game.weather==='夜间'?'晴夜 · 12°C':game.weather==='小雨'?'小雨 · 15°C':'晴朗 · 18°C';$('#modeLabel').textContent=game.mode==='rush'?'高峰模式':game.mode==='night'?'夜间模式':'标准模式';$('#shiftBadge').textContent=game.mode==='night'?'夜班 03':game.mode==='rush'?'高峰 02':'早班 01';document.body.classList.toggle('night',game.mode==='night');
 $('#trackOccupancy').innerHTML=[1,2,3].map(l=>`<${game.lanes[l]?'button':'div'} ${game.lanes[l]?'data-train="'+game.lanes[l]+'"':''} class="lane-status ${game.lanes[l]?'occupied':''}"><span>${l===3?'货运':l+' 股道'}</span><strong>${game.lanes[l]||'空闲'}</strong></${game.lanes[l]?'button':'div'}>`).join('');
 $('#mapEvent').hidden=!game.event;$('#mapEvent').textContent=game.event;$('#latestLog').textContent=game.logs[0]?.text||'';
 const queue=game.active.filter(t=>['queued','ready','working'].includes(t.status)),moving=game.active.filter(t=>['incoming','outgoing'].includes(t.status));
 $('#queueCount').textContent=queue.length;$('#activeCount').textContent=moving.length;
 const selected=game.selectedTrain;if(selected?.status==='done'){const candidate=queue.find(t=>t.status==='ready')||queue[0]||moving[0];if(candidate)game.select(candidate.id)}
 const shown=tab==='queue'?queue:moving;
 $('#trainList').innerHTML=shown.length?shown.map(t=>{const due=Math.ceil(t.deadline-game.time);return `<button class="train-card ${t.id===game.selected?'selected':''}" data-train="${t.id}" aria-pressed="${t.id===game.selected}"><div class="train-card-top"><span class="train-name"><span style="color:${t.color}">${icons.train}</span><strong>${t.id}</strong><span class="cargo-label">${t.cargo}</span></span><span class="train-state ${t.status==='ready'?'ready':''}">${statusNames[t.status]}</span></div><div class="train-card-bottom"><span class="direction-line">${t.dir===1?'西岭':'东港'}<em>→</em>${t.dir===1?'东港':'西岭'}${t.lane?' · '+t.lane+' 股道':''}</span><span class="due ${due<0?'late':''}">${due>=0?'余 '+due+' 秒':'晚点 '+Math.abs(due)+' 秒'}</span></div></button>`}).join(''):`<div class="empty-list">${icons.train}${tab==='queue'?'当前没有待调度列车':'区间内暂无运行列车'}<br><small>${tab==='queue'?'留意下一班到站时间':'开放信号后，列车将在这里显示'}</small></div>`;
 const t=game.selectedTrain;
 $('#selectedDetail').innerHTML=t?`<span>当前选中 <strong>${t.id}</strong></span><span>${t.status==='working'?`${t.passenger?'乘降':'装卸'} <strong>${Math.ceil(t.work)}s</strong>`:t.status==='incoming'||t.status==='outgoing'?`运行进度 <strong>${Math.round(t.progress*100)}%</strong>`:t.lane?`${t.lane} 股道 · ${statusNames[t.status]}`:`计划交付 ${clock(t.deadline)}`}</span>`:'请选择列车';
 for(const side of['west','east']){$$(`#${side}Switch button`).forEach(b=>{b.classList.toggle('active',+b.dataset.lane===game.switches[side]);b.setAttribute('aria-pressed',String(+b.dataset.lane===game.switches[side]));b.title=game.blocks[side]?`进路已锁定：${game.blocks[side]}`:`切至 ${b.dataset.lane} 股道`});$(`#${side}Lock`).textContent=game.blocks[side]?'▣':'◇';$(`#${side}Lock`).title=game.blocks[side]?'进路锁定':'可切换'}
 const route=game.routeInfo();$('#routeMessage').textContent=route.message;$('#routeMessage').classList.toggle('blocked',!route.ok&&game.started);$('#dispatchBtn span').textContent=!game.started?'开始值班 · 准备进站':t?.status==='ready'?'开放信号 · 出站':t?.status==='working'?'装卸中 · 等待完成':t&&['incoming','outgoing'].includes(t.status)?'信号已开放 · 运行中':'开放信号 · 进站';$('#dispatchBtn').disabled=game.ended||!!t&&['incoming','outgoing','working','done'].includes(t.status);$('#dispatchBtn').style.opacity=!route.ok&&game.started?'.65':'1';
 const upcoming=game.trains.find(t=>t.status==='scheduled');$('#nextTrain').textContent=upcoming?`下一班 ${upcoming.id} · ${Math.ceil(upcoming.arrival-game.time)} 秒后从${upcoming.side==='west'?'西岭':'东港'}到达`:'所有计划班次均已到达，请完成运输';
 const timeline=game.trains.filter(t=>t.status!=='done').slice(0,7);$('#timeline').innerHTML=timeline.map(t=>`<button class="timeline-item ${t.status==='scheduled'?'':'now'}" data-train="${t.id}" title="${t.id} ${t.cargo} ${clock(t.arrival)}"><strong>${t.id}</strong><span class="tl-time">${String(Math.floor(t.arrival/60)).padStart(2,'0')}:${String(Math.floor(t.arrival%60)).padStart(2,'0')}</span><small>${t.dir===1?'西岭 → 东港':'东港 → 西岭'}</small></button>`).join('')||'<div class="empty-list">全部列车已交付，优秀的调度！</div>';
 $('#contractDot').hidden=!game.contracts().some(c=>c.value>=c.target&&!game.claimed.includes(c.id));
 if(game.meets>0){$('#missionOverline').textContent='安全会车已完成 · +100 调度积分';$('#missionTitle').textContent='保持线路畅通，完成货运合同';$('#missionHint').textContent=`已交付 ${game.delivered} 班 · 已安排 ${game.meets} 次会车 · 积分 ${game.score}`;$('#missionCount').textContent=game.delivered+' / 14'}else{$('#missionOverline').textContent='你的第一项调度任务';$('#missionTitle').textContent='安排一次安全会车';$('#missionHint').textContent='让两端列车进入不同股道，再依次放行出站。';$('#missionCount').textContent='0 / 1'}
 $$('[data-speed]').forEach(b=>b.classList.toggle('active',+b.dataset.speed===game.speed));
}
function openDialog(type){
 if(!$('#modal').open){modalResume=game.running;game.running=false;$('#modal').showModal()}
 modalType=type;$('#modalEyebrow').textContent='VALLEY RAIL · DISPATCH';
 if(type==='help'){$('#modalTitle').textContent='调度员手册';$('#modalBody').innerHTML=`<p>你负责青岚站两端的单线区间。每班值守 5 分钟，安排 14 趟客货列车安全通过。暂停时也可以规划道岔和进路。</p><div class="modal-card"><span class="number">01</span><div><h3>选择列车，安排进站</h3><p>在待调度列表选择列车。设置入口一侧道岔：1、2 股道可停客货列车，货运股道装卸更快。</p></div></div><div class="modal-card"><span class="number">02</span><div><h3>相向会车，错开股道</h3><p>西端与东端的列车可同时进入不同股道。单线区间、股道和道岔会锁定，防止两车抢占。每次危险放行扣 3 点安全分。</p></div></div><div class="modal-card"><span class="number">03</span><div><h3>完成作业，再放行出站</h3><p>装卸结束后，将出口一侧道岔对齐本车股道，确认区间空闲，再开放信号。相向来车还在区间时必须等待。</p></div></div><div class="modal-card"><span class="number">04</span><div><h3>准点交付，升级设备</h3><p>准点奖励更高，晚点仍可完成。领取运输合同奖励，升级装卸设备和自动出站信号。山谷降雨会降低行车速度。</p></div></div><div class="shortcut-list"><span><kbd>空格</kbd>暂停 / 继续</span><span><kbd>1 2 3</kbd>选中列车的进路</span><span><kbd>Enter</kbd>开放信号</span><span><kbd>R</kbd>复位视角</span></div><button class="modal-primary" data-action="close">了解，返回调度台</button>`}
 if(type==='contracts'){$('#modalTitle').textContent='运输合同';$('#modalBody').innerHTML='<p>每一份准时完成的运单，都让山谷更紧密地连接起来。</p>'+game.contracts().map(c=>`<div class="modal-card"><span class="number">${icons.box}</span><div><h3>${c.name}</h3><p>${c.desc} · ${Math.min(c.value,c.target)} / ${c.target}</p><div class="modal-progress"><span style="width:${Math.min(100,c.value/c.target*100)}%"></span></div></div><button data-claim="${c.id}" ${c.value<c.target||game.claimed.includes(c.id)?'disabled':''}>${game.claimed.includes(c.id)?'已领取':'领取 ¥'+c.reward}</button></div>`).join('')}
 if(type==='upgrades'){$('#modalTitle').textContent='设备与技术';const upgrades=[['loading','高效装卸设备','站内作业时间缩短 40%，对后续到站列车生效。',400],['signals','自动出站联锁','作业结束后自动对齐空闲出口并放行，进站仍由你安排。',700],['bonus','货运服务升级','此后的每一班交付收入提高 25%。',500]];$('#modalBody').innerHTML=`<p>可用运营收入 <strong style="color:var(--accent)">¥${game.money}</strong> · 升级在本次值班立即生效。</p>`+upgrades.map(([key,name,desc,price])=>`<div class="modal-card"><span class="number"><svg><use href="#i-settings"/></svg></span><div><h3>${name}</h3><p>${desc}</p></div><button data-buy="${key}" ${game.upgrades[key]||game.money<price?'disabled':''}>${game.upgrades[key]?'已升级':'¥'+price}</button></div>`).join('')}
 if(type==='scenario'){$('#modalTitle').textContent=game.started?'开始新的值班':'选择你的值班';$('#modalBody').innerHTML=`<p>${game.started?'开始新班次会重置本局进度，已保存的个人最佳成绩会保留。':'三个班次使用同一张地图，每局 5 分钟。推荐先从山谷早班开始。'}</p>`+[['standard','山谷早班','舒缓的清晨，从两列相向列车开始学习调度。','标准'],['rush','高峰挑战','列车更密集，需要预先规划空闲股道和单线顺序。','进阶'],['night','夜间值守','灯光亮起，守护夜色中的客货列车安全通过。','夜景']].map(([id,name,desc,label])=>`<div class="modal-card"><span class="number">${id==='night'?'☾':id==='rush'?'Ⅱ':'Ⅰ'}</span><div><h3>${name} <small>${label}</small></h3><p>${desc}</p></div><button data-mode="${id}">开始</button></div>`).join('')}
 if(type==='logs'){$('#modalTitle').textContent='调度日志';$('#modalBody').innerHTML=game.logs.map(l=>`<div class="log-item ${l.type}"><time>${clock(l.time)}</time><span>${l.text}</span></div>`).join('')}
 if(type==='timetable'){$('#modalTitle').textContent='全日运行计划';$('#modalBody').innerHTML=`<p>本班 ${game.trains.length} 列车，已交付 ${game.delivered} 列。客运列车需使用 1、2 股道。</p><table class="timetable-table"><thead><tr><th>班次</th><th>货物 / 旅客</th><th>方向</th><th>到达入口</th><th>交付期限</th><th>状态</th></tr></thead><tbody>${game.trains.map(t=>`<tr><td>${t.id}</td><td>${t.cargo}</td><td>${t.dir===1?'西 → 东':'东 → 西'}</td><td>${clock(t.arrival)}</td><td>${clock(t.deadline)}</td><td>${statusNames[t.status]}</td></tr>`).join('')}</tbody></table>`}
 if(type==='result'){
  $('#modalTitle').textContent='本班运营报告';let best=game.score;try{best=Math.max(+localStorage.getItem('valley-rail-best')||0,game.score);localStorage.setItem('valley-rail-best',best)}catch{}
  const rating=game.delivered>=12&&game.safety>=90?'王牌调度员':game.delivered>=8?'优秀值班员':game.delivered>=4?'合格调度员':'继续练习，熟悉你的铁路';
  $('#modalBody').innerHTML=`<div class="result-score"><span>${rating}</span><strong>${game.score}</strong><span>调度积分 · 本机最佳 ${best}</span></div><div class="result-grid"><div><strong>${game.delivered}/14</strong><small>完成班次</small></div><div><strong>${game.punctuality}%</strong><small>准点率</small></div><div><strong>${game.safety}</strong><small>安全评分</small></div></div><p style="margin-top:20px">完成 ${game.meets} 次安全会车，剩余运营收入 ¥${game.money}。${game.delivered<14?'还有 '+(14-game.delivered)+' 班未交付；下一班试着优先放行站内已完成作业的列车。':'山谷全线运行顺畅，你完成了所有运输任务。'}</p><button class="modal-primary" data-action="scenario">选择下一班</button>`
 }
 render();
}
function closeDialog(){if($('#modal').open)$('#modal').close();if(modalResume&&!game.ended){game.running=true}modalResume=false;modalType='';render()}
function newGame(mode){if(!['standard','rush','night'].includes(mode))return {ok:false,message:'未知班次'};modalResume=false;$('#modal').close();game.reset(mode);resultShown=false;tab='queue';$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));game.start();scene?.resetCamera();render();toast(`${game.difficulty}开始，祝你调度顺利。`);return {ok:true,message:'新班次已开始'}}
function togglePlay(){if(game.ended){openDialog('scenario');return}if(!game.started)game.start();else game.running=!game.running;render();beep()}
const actions={play:togglePlay,dispatch:()=>dispatch(),help:()=>openDialog('help'),contracts:()=>openDialog('contracts'),upgrades:()=>openDialog('upgrades'),scenario:()=>openDialog('scenario'),logs:()=>openDialog('logs'),timetable:()=>openDialog('timetable'),map:()=>{closeDialog();scene?.resetCamera()},close:closeDialog,zoomIn:()=>scene?.zoom(.83),zoomOut:()=>scene?.zoom(1.17),camera:()=>scene?.resetCamera(),top:()=>scene?.resetCamera(true),sound:()=>{sound=!sound;$('#soundBtn span').textContent=sound?'音效开':'音效关';$('#soundBtn').title=sound?'关闭音效':'打开音效';beep()}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.action)actions[b.dataset.action]?.();if(b.dataset.train)select(b.dataset.train);if(b.dataset.tab){tab=b.dataset.tab;$$('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));render()}if(b.dataset.lane)respond(game.setSwitch(b.dataset.side,+b.dataset.lane));if(b.dataset.speed){game.speed=+b.dataset.speed;render()}if(b.dataset.buy){respond(game.buy(b.dataset.buy));openDialog('upgrades')}if(b.dataset.claim){respond(game.claim(b.dataset.claim));openDialog('contracts')}if(b.dataset.mode)newGame(b.dataset.mode)});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeDialog()});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
document.addEventListener('keydown',e=>{if($('#modal').open||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();togglePlay()}else if(e.key==='Enter'&&e.target===document.body){e.preventDefault();dispatch()}else if(['1','2','3'].includes(e.key)){const t=game.selectedTrain;if(t){const side=t.status==='queued'?t.side:t.dir===1?'east':'west';respond(game.setSwitch(side,+e.key))}}else if(e.key.toLowerCase()==='r')scene?.resetCamera()});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.running){game.running=false;render();toast('你离开了调度台，游戏已自动暂停。')}});
render();
try{const {RailwayScene}=await import('./scene.js');scene=new RailwayScene($('#scene'),select);$('#loading').remove()}catch(error){console.error(error);document.documentElement.dataset.error='true';$('#loading').innerHTML='3D 场景未能启动。<br>请使用支持 WebGL 的浏览器并开启硬件加速。<br><small>调度控制台仍可使用。</small>'}
function frame(now){const dt=Math.min((now-lastTime)/1000,.12);lastTime=now;game.tick(dt*game.speed);scene?.update(game,now/1000);if(now-lastUI>200){render();lastUI=now}if(game.ended&&!resultShown){resultShown=true;openDialog('result');beep()}requestAnimationFrame(frame)}requestAnimationFrame(frame);
// Progressive WebMCP support: the same validated actions as the player controls.
if(document.modelContext?.registerTool){const life=new AbortController();const specs=[
 {name:'read_railway_dispatch',title:'查看铁路调度状态',description:'读取本局时钟、列车、股道、区间占用与安全分。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>game.snapshot()},
 {name:'set_railway_switch',title:'设置铁路道岔',description:'设置西端或东端道岔。已锁定的进路不能切换。',inputSchema:{type:'object',properties:{side:{type:'string',enum:['west','east']},lane:{type:'integer',enum:[1,2,3]}},required:['side','lane'],additionalProperties:false},execute:input=>{if(!input||!['west','east'].includes(input.side)||![1,2,3].includes(input.lane))throw new Error('无效的道岔参数');return respond(game.setSwitch(input.side,input.lane))}},
 {name:'dispatch_railway_train',title:'开放列车信号',description:'对指定列车执行与界面相同的进站或出站放行检查。危险操作将被联锁阻止。需先开始值班。',inputSchema:{type:'object',properties:{trainId:{type:'string'}},required:['trainId'],additionalProperties:false},execute:input=>{if(!input||!game.trains.some(t=>t.id===input.trainId))throw new Error('未知列车');game.select(input.trainId);return respond(game.dispatch(input.trainId))}},
 {name:'start_railway_shift',title:'开始铁路值班',description:'开始尚未启动的值班，不会重置已有进度。',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{if(game.started)return {ok:false,message:'本班已启动'};game.start();render();return {ok:true,message:'值班已开始'}}}
 ];for(const spec of specs){try{Promise.resolve(document.modelContext.registerTool(spec,{signal:life.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true})}
